  "/lib/components/svforge/tiptap/tiptap-extensions.ts": "/**\n * SVForge Tiptap Extensions\n */\nimport { Node, mergeAttributes } from '@tiptap/core';\n\n// ============================================================\n// Visual Heading - Non-semantic heading (span with class)\n// ============================================================\n\nexport interface VisualHeadingOptions {\n\tHTMLAttributes: Record<string, string>;\n\tlevels: number[];\n}\n\ndeclare module '@tiptap/core' {\n\tinterface Commands<ReturnType> {\n\t\tvisualHeading: {\n\t\t\tsetVisualHeading: (attributes: { level: number }) => ReturnType;\n\t\t\ttoggleVisualHeading: (attributes: { level: number }) => ReturnType;\n\t\t\tunsetVisualHeading: () => ReturnType;\n\t\t};\n\t}\n}\n\nexport const VisualHeading = Node.create<VisualHeadingOptions>({\n\tname: 'heading',\n\n\taddOptions() {\n\t\treturn {\n\t\t\tHTMLAttributes: {},\n\t\t\tlevels: [1, 2, 3, 4, 5, 6]\n\t\t};\n\t},\n\n\tcontent: 'inline*',\n\tgroup: 'block',\n\tdefining: true,\n\n\taddAttributes() {\n\t\treturn {\n\t\t\tlevel: {\n\t\t\t\tdefault: 1,\n\t\t\t\trendered: false\n\t\t\t}\n\t\t};\n\t},\n\n\tparseHTML() {\n\t\treturn this.options.levels.map((level) => ({\n\t\t\ttag: `h${level}`,\n\t\t\tattrs: { level }\n\t\t}));\n\t},\n\n\trenderHTML({ node, HTMLAttributes }) {\n\t\tconst level = node.attrs.level as number;\n\t\treturn [\n\t\t\t'span',\n\t\t\tmergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {\n\t\t\t\tclass: `tiptap-heading tiptap-heading-${level}`\n\t\t\t}),\n\t\t\t0\n\t\t];\n\t},\n\n\taddCommands() {\n\t\treturn {\n\t\t\tsetVisualHeading:\n\t\t\t\t(attributes) =>\n\t\t\t\t({ commands }) => {\n\t\t\t\t\tif (!this.options.levels.includes(attributes.level)) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\treturn commands.setNode(this.name, attributes);\n\t\t\t\t},\n\t\t\ttoggleVisualHeading:\n\t\t\t\t(attributes) =>\n\t\t\t\t({ commands }) => {\n\t\t\t\t\tif (!this.options.levels.includes(attributes.level)) {\n\t\t\t\t\t\treturn false;\n\t\t\t\t\t}\n\t\t\t\t\treturn commands.toggleNode(this.name, 'paragraph', attributes);\n\t\t\t\t},\n\t\t\tunsetVisualHeading:\n\t\t\t\t() =>\n\t\t\t\t({ commands }) => {\n\t\t\t\t\treturn commands.setNode('paragraph');\n\t\t\t\t}\n\t\t};\n\t}\n});\n"
